const fromBase64 = (value: string) =>
  Uint8Array.from(atob(value), (character) => character.charCodeAt(0));

export const PNG_1X1 = fromBase64(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=",
);

export const PNG_RGBA_2X1 = fromBase64(
  "iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAAEUlEQVR4nGP4z8Dwn+E/AwMAD/kC/ngnZtwAAAAASUVORK5CYII=",
);

export const JPEG_2X1 = fromBase64(
  "",
);

export const JPEG_ORIENTED_2X1 = fromBase64(
  "",
);

export const WEBP_RGBA_2X1 = fromBase64(
  "UklGRloAAABXRUJQVlA4WAoAAAAQAAAAAQAAAAAAQUxQSAMAAAAA/wAAVlA4IDAAAADQAQCdASoCAAEAAgA0JaACdLoB+AADsAD+8MQL/yC5YXXI1/8gP+QH/ID/+PIAAAA=",
);

export const authHeaders = {
  Authorization: "Bearer test-api-key",
  "Content-Type": "application/json",
};

export async function createUpload(
  fetcher: Fetcher,
  limits: Record<string, number> = {},
): Promise<{ id: string; uploadUrl: string; expiresAt: string }> {
  const response = await fetcher.fetch("https://media.example.com/v1/uploads", {
    method: "POST",
    headers: authHeaders,
    body: JSON.stringify(limits),
  });
  if (response.status !== 201) throw new Error(await response.text());
  return response.json();
}
